package com.alan.thormonitor;
import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
final class HostOverviewView extends LinearLayout {
 final HostStatsUi ui;final TextView name,model,state,percent,charging,power,temp,volts,watts,runtime,cpu,gpu,ram,cpuModel,gpuModel,ramInfo,internal,sd,ufs;
 final HostStatsUi.Ring ring;final HostStatsUi.Bar cpuBar,gpuBar,ramBar,internalBar,sdBar;final Button monitor;
 HostOverviewView(Context c,Runnable insights,Runnable monitoring){super(c);setOrientation(VERTICAL);ui=new HostStatsUi(c);
  LinearLayout header=new LinearLayout(c);header.setGravity(Gravity.CENTER_VERTICAL);LinearLayout names=ui.vertical();name=ui.text("Your Thor",26,true);model=ui.muted("AYN Thor",16);names.addView(name);ui.gap(names,4);names.addView(model);header.addView(names,new LayoutParams(0,-2,1));state=ui.text("",14,true);state.setPadding(ui.dp(12),ui.dp(8),ui.dp(12),ui.dp(8));state.setBackground(ui.shape(ui.p.card,20));header.addView(state);addView(header);ui.gap(this,20);monitor=ui.button("Start monitoring",monitoring);LayoutParams monitorLayout=new LayoutParams(-1,-2);monitorLayout.bottomMargin=ui.dp(14);addView(monitor,monitorLayout);
  LinearLayout battery=ui.card(this,null),top=new LinearLayout(c);battery.setContentDescription("Battery");battery.setOnClickListener(v->insights.run());top.setGravity(Gravity.CENTER_VERTICAL);LinearLayout amount=ui.vertical();amount.addView(ui.muted("Battery",16));percent=ui.text("—",46,true);amount.addView(percent);charging=ui.text("",16,false);power=ui.muted("",14);amount.addView(charging);amount.addView(power);top.addView(amount,new LayoutParams(0,-2,1));ring=new HostStatsUi.Ring(ui);top.addView(ring,new LayoutParams(ui.dp(c.getResources().getConfiguration().screenWidthDp<360?136:160),ui.dp(c.getResources().getConfiguration().screenWidthDp<360?136:160)));battery.addView(top);ui.gap(battery,16);View line=new View(c);line.setBackgroundColor(ui.p.border);battery.addView(line,new LayoutParams(-1,ui.dp(1)));ui.gap(battery,14);LinearLayout metrics=ui.vertical();String[] labels={"Temperature","Voltage","USB input"};TextView[] values=new TextView[3];int columns=c.getResources().getConfiguration().fontScale>1.25f||c.getResources().getConfiguration().screenWidthDp<360?2:3;for(int i=0;i<3;i+=columns){LinearLayout row=new LinearLayout(c);for(int col=0;col<columns;col++){if(i+col<3)values[i+col]=ui.metric(row,labels[i+col]);else row.addView(new Space(c),new LayoutParams(0,1,1));}metrics.addView(row);if(i+columns<3)ui.gap(metrics,12);}temp=values[0];volts=values[1];watts=values[2];battery.addView(metrics);ui.gap(battery,16);battery.addView(ui.muted("Estimated runtime",14));runtime=ui.text("Collecting usage history",18,true);battery.addView(runtime);
  Button history=ui.button("Battery insights",insights);addView(history,new LayoutParams(-1,-2));ui.gap(this,14);
  LinearLayout perf=ui.card(this,"Performance");TextView[] refs=new TextView[2];cpuBar=usage(perf,"CPU",ui.p.rainbow?HostPalette.RAINBOW[0]:ui.p.accent,refs);cpu=refs[0];cpuModel=refs[1];gpuBar=usage(perf,"GPU",ui.p.rainbow?HostPalette.RAINBOW[1]:ui.p.accent,refs);gpu=refs[0];gpuModel=refs[1];ramBar=usage(perf,"RAM",ui.p.rainbow?HostPalette.RAINBOW[3]:ui.p.accent,refs);ram=refs[0];ramInfo=refs[1];
  LinearLayout storage=ui.card(this,null),storageTitle=new LinearLayout(c);storage.setContentDescription("Internal storage");storageTitle.setGravity(Gravity.CENTER_VERTICAL);storageTitle.addView(ui.text("Internal storage",18,true),new LayoutParams(0,-2,1));ufs=ui.text("UFS —",18,true);ufs.setPadding(ui.dp(12),ui.dp(6),ui.dp(12),ui.dp(6));ufs.setBackground(ui.shape(ui.p.bg,12));storageTitle.addView(ufs);storage.addView(storageTitle);ui.gap(storage,14);internal=ui.text("—",22,true);storage.addView(internal);ui.gap(storage,12);internalBar=new HostStatsUi.Bar(ui,ui.p.accent);storage.addView(internalBar,new LayoutParams(-1,ui.dp(7)));
  LinearLayout card=ui.card(this,"microSD card");sd=ui.text("Checking storage…",22,true);card.addView(sd);ui.gap(card,12);sdBar=new HostStatsUi.Bar(ui,ui.p.rainbow?HostPalette.RAINBOW[1]:ui.p.accent);card.addView(sdBar,new LayoutParams(-1,ui.dp(7)));

 }
 HostStatsUi.Bar usage(LinearLayout parent,String label,int color,TextView[] refs){LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);row.addView(ui.text(label,16,true),new LayoutParams(0,-2,1));TextView value=ui.text("—",22,true);row.addView(value);parent.addView(row);TextView info=ui.muted("",14);parent.addView(info);ui.gap(parent,10);HostStatsUi.Bar bar=new HostStatsUi.Bar(ui,color);parent.addView(bar,new LayoutParams(-1,ui.dp(7)));ui.gap(parent,18);refs[0]=value;refs[1]=info;return bar;}
 void update(JSONObject j,List<BatterySample> history){
  name.setText(j.optString("device_name","Your Thor"));String variant=j.optString("variant","");model.setText("AYN Thor"+(!variant.isEmpty()&&!variant.equals("null")?" "+variant:""));state.setText(MonitorService.running?(ui.c.getSharedPreferences("monitor",0).getBoolean("rest_suspended",false)?"Keep-alive paused":"Monitoring"):"Stopped");monitor.setVisibility(MonitorService.running?GONE:VISIBLE);
  double level=HostStatsUi.number(j,"battery_percent");percent.setText(HostStatsUi.value(level,"%.0f%%"));charging.setText(HostStatsUi.charging(j));power.setText(HostStatsUi.power(j));ring.set(level,j.optInt("battery_status_code")==2);temp.setText(HostStatsUi.value(HostStatsUi.number(j,"battery_temperature_c"),"%.1f°C"));volts.setText(HostStatsUi.value(HostStatsUi.number(j,"battery_voltage_mv")/1000,"%.2f V"));watts.setText(HostStatsUi.value(HostStatsUi.number(j,"input_watts"),"%.1f W"));runtime.setText(BatteryAnalysis.runtime(history,HostStatsUi.sample(j)).label);
  double cpuPct=j.optLong("cpu_window_ms")>=1000?HostStatsUi.number(j,"cpu_percent"):Double.NaN,gpuPct=HostStatsUi.number(j,"gpu_percent"),total=HostStatsUi.number(j,"ram_total_bytes"),free=HostStatsUi.number(j,"ram_available_bytes"),ramPct=total>0&&free>=0&&free<=total?(total-free)/total*100:Double.NaN;
  cpu.setText(HostStatsUi.value(cpuPct,"%.1f%%"));gpu.setText(HostStatsUi.value(gpuPct,"%.1f%%"));ram.setText(HostStatsUi.value(ramPct,"%.0f%%"));cpuBar.set(cpuPct/100);gpuBar.set(gpuPct/100);ramBar.set(ramPct/100);cpuModel.setText(j.optString("cpu_name","Unavailable")+" · "+Math.max(1,Math.round(j.optLong("cpu_window_ms")/1000.0))+" s average · all cores");gpuModel.setText(j.optString("gpu_name","Unavailable"));ramInfo.setText(Double.isFinite(ramPct)?HostStatsUi.capacity(total-free)+" of "+HostStatsUi.capacity(total)+" used":"Unavailable");
  double size=HostStatsUi.number(j,"data_total_bytes"),available=HostStatsUi.number(j,"data_available_bytes");internal.setText(HostStatsUi.capacity(available)+" free of "+HostStatsUi.capacity(size));internalBar.set(size>0?(size-available)/size:Double.NaN);String version=j.optString("ufs_version","");ufs.setText(version.equals("4.0")||version.equals("3.1")?"UFS "+version:"UFS unknown");
  String sdState=j.optString("sd_state");double sdTotal=HostStatsUi.number(j,"sd_total_bytes"),sdFree=HostStatsUi.number(j,"sd_available_bytes");boolean mounted=sdState.equals("mounted")||sdState.equals("read_only");sd.setText(mounted?HostStatsUi.capacity(sdFree)+" free of "+HostStatsUi.capacity(sdTotal)+(sdState.equals("read_only")?"\nRead only":""):sdState.equals("not_present")?"No microSD card detected":sdState.equals("not_mounted")?"microSD is not mounted":"Storage unavailable");sdBar.set(mounted&&sdTotal>0?(sdTotal-sdFree)/sdTotal:Double.NaN);sdBar.setVisibility(mounted?VISIBLE:GONE);
 }
}
